// Réponse de l'API CleanMatch : { missions: [...] } (ou directement un tableau).
// On re-filtre côté n8n par sécurité, puis on construit UNE relance groupée
// (découpée en plusieurs messages si elle dépasse la limite Discord de 2000 caractères).
const DELAI_JOURS = 3;
const TAILLE_MAX_MESSAGE = 1900;
const UN_JOUR_MS = 24 * 60 * 60 * 1000;

const reponse = $input.first().json;
const missions = Array.isArray(reponse)
  ? reponse
  : Array.isArray(reponse.missions) ? reponse.missions : [];

const maintenant = Date.now();

function formatDate(valeur) {
  if (!valeur) return '?';
  const d = new Date(valeur);
  if (Number.isNaN(d.getTime())) return String(valeur);
  const jj = String(d.getUTCDate()).padStart(2, '0');
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  return `${jj}/${mm}/${d.getUTCFullYear()}`;
}

function ageEnMs(valeur) {
  const d = new Date(valeur);
  return Number.isNaN(d.getTime()) ? null : maintenant - d.getTime();
}

const aRelancer = missions
  .filter((m) => {
    if (m.statut && m.statut !== 'OUVERTE') return false;
    if (Number(m.nbCandidaturesAcceptees ?? 0) > 0) return false;
    const age = ageEnMs(m.createdAt);
    return age !== null && age > DELAI_JOURS * UN_JOUR_MS; // "plus de 3 jours"
  })
  // Les plus anciennes en premier : ce sont les plus urgentes.
  .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));

if (aRelancer.length === 0) {
  return [{ json: { count: 0, message: '' } }];
}

const entete = [
  `**Relance CleanMatch — ${formatDate(new Date().toISOString())}**`,
  `${aRelancer.length} mission(s) ouverte(s) depuis plus de ${DELAI_JOURS} jours sans candidature acceptée :`,
].join('\n');

const lignes = aRelancer.map((m) => {
  const nb = Number(m.nbCandidatures ?? 0);
  const pluriel = nb > 1 ? 's' : '';
  const entreprise = m.entreprise && m.entreprise.raisonSociale ? ` (${m.entreprise.raisonSociale})` : '';
  const jours = Math.floor(ageEnMs(m.createdAt) / UN_JOUR_MS);
  return `- **${m.intitule}**${entreprise} — ${m.ville || 'ville non précisée'} — publiée le ${formatDate(m.createdAt)} (il y a ${jours} j) — ${nb} candidature${pluriel} reçue${pluriel}`;
});

const messages = [];
let courant = entete;
for (const ligne of lignes) {
  if ((courant + '\n' + ligne).length > TAILLE_MAX_MESSAGE) {
    messages.push(courant);
    courant = ligne;
  } else {
    courant += '\n' + ligne;
  }
}
messages.push(courant);

return messages.map((message, index) => ({
  json: { count: aRelancer.length, partie: index + 1, parties: messages.length, message },
}));
